select pg_catalog.pg_current_wal_lsn() as c0, sample_0.payload as c1, pg_catalog.pg_stat_get_bgwriter_requested_checkpoints() as c2 from public.events_other as sample_0 tablesample system (10) where pg_catalog.date_trunc( cast(pg_catalog.system_user() as text), cast(sample_0.occurred_at as timestamptz), cast((select bio from public.users limit 1 offset 4) as text)) > pg_catalog.clock_timestamp() limit 69;
